"use client";

import { useEffect, useRef } from "react";
import { createSupabaseBrowserClient } from "@/lib/supabase/client";
import { safeNext } from "@/lib/routes";

// Starts Google OAuth in the browser that loads this page.
//
// The desktop app opens THIS url in the SYSTEM browser (not the Electron window)
// and Google's PKCE requires the code_verifier — generated by signInWithOAuth — to
// live in the same browser that later exchanges the code at /auth/callback. Call
// signInWithOAuth in the Electron window and the verifier is stranded there while
// the exchange happens in the system browser, so it fails. Doing it here keeps
// both halves in the system browser.
export default function GoogleStart() {
  // Start OAuth once per page load, never twice.
  //
  // Every signInWithOAuth mints a fresh PKCE code_verifier and OVERWRITES the one
  // in storage. A second start therefore strands the first: Google comes back
  // with a code belonging to the earlier flow, the stored verifier belongs to the
  // later one, and Supabase answers "Unable to exchange external code" — the
  // sign-in fails with no clue as to why. React runs effects twice in
  // development, which is enough on its own to cause it.
  const started = useRef(false);
  useEffect(() => {
    if (started.current) return;
    started.current = true;
    const params = new URLSearchParams(window.location.search);
    const nextParam = params.get("next");
    const next = safeNext(nextParam);
    const supabase = createSupabaseBrowserClient();
    void supabase.auth.signInWithOAuth({
      provider: "google",
      options: {
        redirectTo: `${window.location.origin}/auth/callback?next=${encodeURIComponent(next)}`,
      },
    });
  }, []);

  return (
    <main className="flex min-h-screen items-center justify-center px-4 text-sm text-muted-foreground">
      Redirecting to Google…
    </main>
  );
}
